-- CAPEX DOA bands from 'Granules DOA-23.02.26.xlsx'. Creates table if missing + idempotent seed.
BEGIN;
CREATE TABLE IF NOT EXISTS pmo_doa_matrix (
  id serial PRIMARY KEY,
  entity text NOT NULL DEFAULT '*',
  category text NOT NULL DEFAULT '*',
  kind text NOT NULL DEFAULT '*',
  min_inr numeric(15,2) NOT NULL DEFAULT '0',
  max_inr numeric(15,2),
  approver_roles jsonb NOT NULL DEFAULT '[]'::jsonb,
  active boolean NOT NULL DEFAULT true,
  label text NOT NULL DEFAULT '',
  notes text NOT NULL DEFAULT '',
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
DELETE FROM pmo_doa_matrix WHERE notes = 'seed:capex-doa-23.02.26';
COMMIT;
